#
# 现在统一由下面两个函数解析，**不再有任何脚本拼相对路径 `.qc/…`**：
#
#   1. 环境变量 `MATSCI_QC_DIR`（显式指定，最高优先级）
#   2. 库根 `.qc/`        —— **新产出的工作目录**（原设计意图，已被 .gitignore 覆盖）
#   3. `_archive/qc/qc-working/.qc/` —— 历史工作目录，**只读回退**：
#        真源文件（`queue.json` / `LEDGER.md` / `manifest.json`）在这里，
#        迁走后未重建 `.qc/` 时仍能读到。
#      ⚠️ 2026-10-11：`_archive` 做过一次归并（13→5 组），原 `_archive/qc-working/`
#         现在是 `_archive/qc/qc-working/`。路径常量必须跟着改，否则**只读回退会静默失效**
#         （`qc_input("LEDGER.md")` 会变成"找不到"而不是报错）。
#
# 写盘一律写进「库根 `.qc/`」，绝不写进 `_archive/`——归档层只进不出。

QC_DIR_ENV = "MATSCI_QC_DIR"
QC_ARCHIVE = "_archive/qc/qc-working/.qc"


def qc_work_dir(create=False):
    """返回 QC 工作目录（绝对路径）。

    create=True 时确保目录存在（写盘脚本应先调用一次）。
    解析顺序见本节顶部注释。
    """
    env = os.environ.get(QC_DIR_ENV)
    if env:
        d = env if os.path.isabs(env) else os.path.join(VAULT, env)
        if create:
            os.makedirs(d, exist_ok=True)
        return d
    root = os.path.join(VAULT, ".qc")
    if os.path.isdir(root) or create:
        if create:
            os.makedirs(root, exist_ok=True)
        return root
    arch = os.path.join(VAULT, *QC_ARCHIVE.split("/"))
    return arch if os.path.isdir(arch) else root


def qc_file(*parts, create=False):
    """QC 工作目录下的某个文件（绝对路径）。

    ⚠️ **写盘脚本必须先 `qc_work_dir(create=True)`**（或对本函数传 create=True），
    否则目录尚未建立时会解析到**归档目录**。归档层只进不出——此处对「已知产出物」
    加一道断言，防止误写进 `_archive/`。
    """
    d = qc_work_dir(create=create)
    if create and os.path.basename(d) == ".qc" and "_archive" in d.replace("/", "\\"):
        raise RuntimeError(
            "拒绝写盘：QC 工作目录解析到了归档层 %s。"
            "请先 qc_work_dir(create=True) 或设置 %s。" % (d, QC_DIR_ENV))
    return os.path.join(d, *parts)


def qc_input(*parts):
    """QC **输入**文件：优先新工作目录，不存在则回退历史归档。

    `queue.json` / `LEDGER.md` 这类「真源」文件在归档里，迁走后若未重建
    `.qc/`，本函数保证仍能读到；而 `--write` 类产出仍写新 `.qc/`。
    """
    new = os.path.join(qc_work_dir(), *parts)
    if os.path.exists(new):
        return new
    arch = os.path.join(VAULT, *QC_ARCHIVE.split("/"), *parts)
    return arch if os.path.exists(arch) else new


# ---------------------------------------------------------------- frontmatter 重组
#
# 🔴 这是本库**代价最高**的一类失效：frontmatter 静默解析不出来（页面能正常打开、
#    正文可读，人工浏览完全看不出），曾一次写坏 124 页。
#    已记录的两个成因**同源**——都是「`---` 后缺换行」：
#      ① 开围栏：`"---" + fm`  ⇒ `---summary: "..."`（前缀被当同一行）
#      ② 闭合后：`"...---" + body` ⇒ `---# 标题`
#    ⇒ 凡重组 frontmatter 一律走本函数，**不要再手写字符串拼接**。
#    实证：本次复核中 `qc_fix_yaml.py` 与 `kb_fix_frontmatter_quotes.py`
#    各犯一条，均由 selftest 抓出（前者开围栏、后者闭合）。

def join_frontmatter(fm_text, body):
    """把 frontmatter 文本与正文重组为**可被 split_frontmatter 读出**的全文。

    自动保证：开围栏 `---` 后必有换行、闭合 `---` 后必有换行。
    `fm_text` 两端的换行会被归一化，故调用方无需关心其首尾空白。
    """
    return "---\n" + (fm_text or "").strip("\n") + "\n---\n" + (body or "").lstrip("\n")


def json_safe(value):
    """移除 surrogate，保证历史文本也能序列化为严格 UTF-8 JSON。"""
    if isinstance(value, str):
        return value.encode("utf-8", errors="replace").decode("utf-8")
    if isinstance(value, dict):
        return {json_safe(k): json_safe(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [json_safe(v) for v in value]
    return value


def json_dumps(value, **kwargs):
    return json.dumps(json_safe(value), **kwargs)


def write_json_atomic(path, value, **kwargs):
    """同目录临时文件 + os.replace，避免半截 JSON 索引。"""
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="\n") as f:
        f.write(json_dumps(value, **kwargs))
    os.replace(tmp, path)


# ---------------------------------------------------------------- 控制台输出编码
#
# 🔴 由来（2026-10-14 诊断意见 P1-3）：全库 30+ 个脚本各写一份
#        `sys.stdout.reconfigure(encoding="utf-8", errors="replace")`
#    但 **控制台代码页仍是 936（GBK）时**，Python 写出 UTF-8 字节、控制台按 GBK 解码
#    ⇒ 中文全成 mojibake（`kb_stats` / `kb_route` / `kb_search --resolve` 实测）。
#    对 AI 调用无碍（管道里字节是好的），但**人直接看工具输出是坏的**，
#    而「工具可被人工验证」正是本库自检体系的最后一环。
#
# 判定策略（**不赌单一事实**，因为「谁在解码」随宿主变化）：
#   · stdout 不是终端（管道/重定向/子进程捕获）⇒ 强制 UTF-8。
#     调用方（如 lit_finish 用 encoding="utf-8" 捕获）与 Agent 都按 UTF-8 读，字节必须自洽。
#   · stdout 是终端 ⇒ **先试着把控制台代码页改成 65001**（SetConsoleOutputCP）。
#       成功 → 用 UTF-8（终端与写出的字节一致，且保留化学式上下标等字符）。
#       失败 → **回落到控制台原本的编码**，至少中文是可读的。
#     ⚠️ 不能无条件 reconfigure：CP936 终端 + UTF-8 字节 = 整屏乱码。
#     这正是本库「**写出了缺省值也要验证它在起作用**」那条方法论的适用处
#     ——旧写法「声明了 UTF-8」却在 cp936 终端上没生效。
#
# 收敛到 kb_lib 的唯一原因与 `parse_budget`/`TYPE_DIR` 相同：**同一事实多处维护必然漂移**。

_console_encoding_done = False


def console_encoding():
    """按上文策略设置 stdout/stderr 编码；返回实际生效的编码名。

    幂等：重复调用只做一次（供被 import 时立即使用）。
    任何异常都吞掉——编码设置失败绝不该让一个工具跑不起来。
    """
    global _console_encoding_done
    if _console_encoding_done:
        return getattr(sys.stdout, "encoding", "") or ""
    _console_encoding_done = True
    try:
        is_tty = False
        try:
            is_tty = bool(sys.stdout.isatty())
        except Exception:                                  # noqa: BLE001
            is_tty = False
        want = "utf-8"
        if is_tty:
            cp = None
            try:
                import ctypes
                k = ctypes.windll.kernel32                  # 仅 Windows 有
                cp = int(k.GetConsoleOutputCP())
                if cp != 65001:
                    # 试着把控制台切到 UTF-8；失败（返回值 0）就按原代码页来
                    if k.SetConsoleOutputCP(65001):
                        cp = 65001
            except Exception:                              # noqa: BLE001
                cp = None
            if cp and cp != 65001:
                # 切不过去 ⇒ 用控制台原编码，中文才可读（宁可不统一，不可乱码）
                import codecs
                want = "cp%d" % cp if codecs.lookup("cp%d" % cp) else want
        for stream in (sys.stdout, sys.stderr):
            try:
                stream.reconfigure(encoding=want, errors="replace")
            except Exception:                              # noqa: BLE001
                pass
        return want
    except Exception:                                      # noqa: BLE001
        return getattr(sys.stdout, "encoding", "") or ""


